export const FRAME = {
    data: 0,
    headers: 1,
    priority: 2,
    rstStream: 3,
    settings: 4,
    pushPromise: 5,
    ping: 6,
    goaway: 7,
    windowUpdate: 8,
    continuation: 9,
};
export const FLAG = {
    ack: 0x1,
    endStream: 0x1,
    endHeaders: 0x4,
    padded: 0x8,
    priority: 0x20,
};
export const CLIENT_PREFACE = new TextEncoder().encode("PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n");
export function concat(chunks) {
    const output = new Uint8Array(chunks.reduce((size, chunk) => size + chunk.byteLength, 0));
    let offset = 0;
    for (const chunk of chunks) {
        output.set(chunk, offset);
        offset += chunk.byteLength;
    }
    return output;
}
export function encodeFrame(frame) {
    if (frame.payload.byteLength > 16777215) {
        throw new Error("HTTP/2 frame payload is too large");
    }
    const output = new Uint8Array(9 + frame.payload.byteLength);
    const view = new DataView(output.buffer);
    output[0] = frame.payload.byteLength >>> 16;
    output[1] = frame.payload.byteLength >>> 8;
    output[2] = frame.payload.byteLength;
    output[3] = frame.type;
    output[4] = frame.flags;
    view.setUint32(5, frame.streamId & 2147483647);
    output.set(frame.payload, 9);
    return output;
}
export function writeFrame(output, frame) {
    output.blockingWriteAndFlush(encodeFrame(frame));
}
export class FrameReader {
    #input;
    #u64;
    #buffer = new Uint8Array();
    constructor(input, u64 = BigInt) {
        this.#input = input;
        this.#u64 = u64;
    }
    readBytes(length) {
        while (this.#buffer.byteLength < length) {
            const requested = this.#u64(Math.max(65536, length - this.#buffer.byteLength));
            const chunk = this.#input.blockingRead(requested);
            if (chunk.byteLength === 0) {
                continue;
            }
            this.#buffer = concat([this.#buffer, chunk]);
        }
        const result = this.#buffer.slice(0, length);
        this.#buffer = this.#buffer.slice(length);
        return result;
    }
    readFrame() {
        const header = this.readBytes(9);
        const length = (header[0] << 16) | (header[1] << 8) | header[2];
        return {
            type: header[3],
            flags: header[4],
            streamId: new DataView(header.buffer, header.byteOffset, header.byteLength).getUint32(5) &
                2147483647,
            payload: this.readBytes(length),
        };
    }
}
export function uint32(value) {
    const output = new Uint8Array(4);
    new DataView(output.buffer).setUint32(0, value);
    return output;
}
export function parseUint32(value, offset = 0) {
    return new DataView(value.buffer, value.byteOffset, value.byteLength).getUint32(offset);
}
